#nullable enable
using Wolverine.Marten;
using Drafting.Contracts;

namespace Drafting.Slices.Drafting;

/// <summary>
/// THE SAME STATE CHANGE, WITHOUT HTTP. Same model, same GWTs, same fold — a plain Wolverine message handler
/// invoked in process. This is what a slice looks like when its command is issued by an automation, a saga,
/// another service over a broker, or a test, rather than typed by a person at a screen.
///
/// The middleware is identical: <c>[WriteAggregate]</c> fetches and folds the stream and carries its version
/// into the append. Only the transport and the way a refusal travels are different.
///
/// FOUR DIFFERENCES FROM THE HTTP VERSION, and none of them is cosmetic.
///
/// 1. THE IDENTITY IS NAMED EXPLICITLY. With no route there is no <c>{emailId}</c> to match, so Wolverine falls
///    back to a convention: a member on the command called <c>&lt;AggregateType&gt;Id</c>. The aggregate type here is
///    <c>ReviseSubjectState</c>, so the convention looks for <c>ReviseSubjectStateId</c> and finds nothing —
///    the kit names state types per SLICE (aggregates are per slice, deliberately) and that naming defeats
///    the convention outright. <c>[WriteAggregate(nameof(...))]</c> says it out loud instead, and survives a
///    rename, so it is the better form even where the convention would have worked.
///
/// 2. A REFUSAL CANNOT BE ProblemDetails. There is no HTTP caller to hand one to. The handler returns an
///    outcome the caller reads — the third rejection shape, and the invariant across all of them is that the
///    RULE NAME is the machine-readable part.
///
/// 3. A MISSING STREAM IS SILENT BY DEFAULT, and this is the trap. Left required, an HTTP endpoint answers
///    404; a MESSAGE handler "logs that the aggregate was not found and stops processing" — the message is
///    discarded. A GWT that says <c>then="error: NotDrafted"</c> would then be unobservable: nothing fails,
///    nothing is returned, and the rule quietly does not exist. <c>Required = false</c> is not a preference
///    here, it is what makes the rule assertable at all.
///
/// 4. NO VALIDATOR RUNS. <c>UseFluentValidation()</c> is wired for both, but SubjectRequired is written
///    against the HTTP pipeline's middleware. Anything invoking this handler directly gets no periphery
///    check — see the test, which asserts the asymmetry rather than pretending it away.
/// </summary>
public static class ReviseSubjectHandler
{
    /// <summary>
    /// Returns <c>(ReviseOutcome, Events)</c>, and the tuple is the whole trick.
    ///
    /// In the aggregate handler workflow a returned value is APPENDED as an event, so an outcome object
    /// returned on its own would be written to the stream — which is not an event and has no business there.
    /// <c>Events</c> is Wolverine's explicit "these go on the stream" collection, which leaves the other slot
    /// free to be the response <c>InvokeAsync&lt;T&gt;</c> hands back. An empty <c>Events</c> appends nothing,
    /// so a refusal is simply a tuple with nothing in it.
    ///
    /// The first attempt used an <c>out</c> parameter for the event. Wolverine's code generation rejected it
    /// outright — <c>CS1615: Argument 1 may not be passed with the 'out' keyword</c> — and, because the
    /// generated handler failed to COMPILE, it took the whole host down and every HTTP test with it. A
    /// codegen failure in one handler is not a local problem.
    /// </summary>
    public static (ReviseOutcome, Events) Handle(
        ReviseSubject command,
        [WriteAggregate(nameof(ReviseSubject.EmailId), Required = false)] ReviseSubjectState? draft)
    {
        var events = new Events();

        if (draft is not { Drafted: true })
            return (ReviseOutcome.Rejected("NotDrafted",
                $"No draft {command.EmailId} exists, so there is no subject to revise."), events);

        if (string.Equals(draft.Subject, command.Subject, StringComparison.Ordinal))
            return (ReviseOutcome.Rejected("NothingChanged",
                "The subject submitted is the one the draft already has."), events);

        events += new SubjectRevised(command.EmailId, command.Subject, DateTimeOffset.UtcNow);
        return (ReviseOutcome.Revised(command.EmailId), events);
    }
}

/// <summary>
/// What the caller reads back. Same shape as an automation's outcome, and for the same reason: no HTTP
/// caller exists, so <c>Rule</c> carries what <c>Title</c> would have.
/// </summary>
public sealed record ReviseOutcome(Guid? EmailId, string? Rule, string? Detail)
{
    public bool WasRevised => Rule is null;

    public static ReviseOutcome Revised(Guid emailId) => new(emailId, null, null);

    public static ReviseOutcome Rejected(string rule, string detail) => new(null, rule, detail);
}
